from __future__ import annotations

import json
import os
import shutil
from pathlib import Path

if __package__:
    from .material_profiles import resolve_task_material_profile
else:
    from material_profiles import resolve_task_material_profile


APP_ROOT = Path(__file__).resolve().parent
TASKS_ROOT = APP_ROOT / "tasks"
DEFAULT_WORKSPACE_ROOT = Path(os.environ.get("SCI_BENCH_WORKSPACE_ROOT", "/workspace"))


def normalize_task_id(task_id: str) -> str:
    stripped = task_id.strip()
    if stripped.startswith("task_"):
        return stripped
    if not stripped.isdigit():
        raise ValueError("task_id must be numeric, e.g. 001, or task_NNN")
    return f"task_{int(stripped):03d}"


def load_task_metadata(task_dir: Path) -> dict[str, object]:
    metadata_path = task_dir / "metadata.json"
    with metadata_path.open("r", encoding="utf-8") as handle:
        metadata = json.load(handle)

    if not isinstance(metadata, dict):
        raise ValueError(f"Task metadata must be a JSON object: {metadata_path}")
    return metadata


def resolve_public_task(task_id: str) -> tuple[str, Path]:
    normalized = normalize_task_id(task_id)
    task_dir = TASKS_ROOT / normalized

    if not task_dir.is_dir():
        raise FileNotFoundError(f"Task directory not found: {task_dir}")

    return normalized, task_dir


def clear_directory(path: Path) -> None:
    for child in path.iterdir():
        if child.is_dir():
            shutil.rmtree(child)
        else:
            child.unlink()


def copy_agent_visible_files(
    task_dir: Path,
    workspace_task_dir: Path,
    *,
    material_profile: str | None = None,
) -> None:
    profile = resolve_task_material_profile(task_dir, material_profile)
    visible_entries = profile.visible_entries

    ignore = shutil.ignore_patterns("__pycache__", ".pytest_cache")

    for entry in visible_entries:
        if not isinstance(entry, str):
            raise ValueError(
                f"Invalid agent-visible entry in {task_dir / 'metadata.json'}: {entry!r}"
            )

        source_path = task_dir / entry
        if not source_path.exists():
            raise FileNotFoundError(f"Agent-visible path not found: {source_path}")

        destination_path = workspace_task_dir / entry
        destination_path.parent.mkdir(parents=True, exist_ok=True)

        if source_path.is_dir():
            shutil.copytree(source_path, destination_path, ignore=ignore, dirs_exist_ok=True)
        else:
            shutil.copy2(source_path, destination_path)


def prepare_workspace(
    task_id: str,
    force: bool = False,
    *,
    material_profile: str | None = None,
) -> Path:
    normalized, task_dir = resolve_public_task(task_id)
    workspace_task_dir = DEFAULT_WORKSPACE_ROOT / normalized

    if workspace_task_dir.exists():
        if not force:
            return workspace_task_dir
        clear_directory(workspace_task_dir)

    DEFAULT_WORKSPACE_ROOT.mkdir(parents=True, exist_ok=True)
    workspace_task_dir.mkdir(parents=True, exist_ok=True)
    copy_agent_visible_files(
        task_dir,
        workspace_task_dir,
        material_profile=material_profile,
    )
    return workspace_task_dir

"""Task-local auxiliary-material profile resolution.

The sidecar declaration is intentionally not part of an agent-visible payload.
It is consumed while task images are staged, then the staged metadata is
rewritten to the resolved profile allowlist.
"""

from __future__ import annotations

import hashlib
import json
from dataclasses import dataclass
from pathlib import Path
from typing import Any


WITH_AUXILIARY = "with_auxiliary"
WITHOUT_AUXILIARY = "without_auxiliary"
DEFAULT_MATERIAL_PROFILE = WITH_AUXILIARY
MATERIAL_PROFILES = (WITH_AUXILIARY, WITHOUT_AUXILIARY)
DECLARATION_FILENAME = "auxiliary_materials.json"
SUPPORTED_AUXILIARY_KINDS = frozenset(
    {
        "scientific_reference",
        "reference_bundle",
        "method_note",
        "supplementary_context",
        "reference_implementation",
    }
)
CORE_PROFILE_TEXT_FILES = (
    "instruction.md",
    "problem_desc.txt",
    "reproduction.md",
)


@dataclass(frozen=True)
class AuxiliaryMaterial:
    path: str
    kind: str

    def as_dict(self) -> dict[str, str]:
        return {"path": self.path, "kind": self.kind}


@dataclass(frozen=True)
class TaskMaterialProfile:
    """Resolved task entries for one agent-visible material profile."""

    name: str
    full_entries: tuple[str, ...]
    visible_entries: tuple[str, ...]
    auxiliary_materials: tuple[AuxiliaryMaterial, ...]
    declaration_sha256: str | None

    @property
    def removed_materials(self) -> tuple[AuxiliaryMaterial, ...]:
        if self.name == WITHOUT_AUXILIARY:
            return self.auxiliary_materials
        return ()

    def digest(self) -> str:
        payload = {
            "schema_version": 1,
            "profile": self.name,
            "full_entries": list(self.full_entries),
            "visible_entries": list(self.visible_entries),
            "auxiliary_materials": [item.as_dict() for item in self.auxiliary_materials],
            "declaration_sha256": self.declaration_sha256,
        }
        encoded = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode(
            "utf-8"
        )
        return hashlib.sha256(encoded).hexdigest()

    def as_record(self) -> dict[str, object]:
        return {
            "name": self.name,
            "declaration_sha256": self.declaration_sha256,
            "profile_digest": self.digest(),
            "full_visible_entries": list(self.full_entries),
            "visible_entries": list(self.visible_entries),
            "auxiliary_materials": [item.as_dict() for item in self.auxiliary_materials],
            "removed_auxiliary_materials": [
                item.as_dict() for item in self.removed_materials
            ],
        }


def normalize_material_profile(value: str | None) -> str:
    profile = (value or DEFAULT_MATERIAL_PROFILE).strip()
    if profile not in MATERIAL_PROFILES:
        raise ValueError(
            f"Unsupported material profile: {profile!r}. "
            f"Expected one of: {', '.join(MATERIAL_PROFILES)}"
        )
    return profile


def declaration_path(task_dir: Path) -> Path:
    return task_dir / DECLARATION_FILENAME


def load_json_object(path: Path) -> dict[str, Any]:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise ValueError(f"Invalid JSON: {path}") from exc
    if not isinstance(payload, dict):
        raise ValueError(f"Expected a JSON object: {path}")
    return payload


def _validate_relative_path(value: object, *, label: str) -> str:
    if not isinstance(value, str) or not value:
        raise ValueError(f"{label} must be a non-empty string")
    if "\\" in value:
        raise ValueError(f"{label} must use POSIX-style relative paths: {value!r}")
    path = Path(value)
    if value == "." or path.is_absolute() or ".." in path.parts:
        raise ValueError(f"Unsafe {label}: {value!r}")
    return value


def _metadata_entries(task_dir: Path) -> tuple[str, ...]:
    metadata_path = task_dir / "metadata.json"
    metadata = load_json_object(metadata_path)
    entries = metadata.get("agent_entry_files")
    if not isinstance(entries, list) or not entries:
        raise ValueError(f"Missing non-empty agent_entry_files: {metadata_path}")

    normalized: list[str] = []
    seen: set[str] = set()
    for index, entry in enumerate(entries):
        path = _validate_relative_path(entry, label=f"agent_entry_files[{index}]")
        if path in seen:
            raise ValueError(f"Duplicate agent entry in {metadata_path}: {path!r}")
        if not (task_dir / path).exists():
            raise FileNotFoundError(f"Agent-visible path does not exist: {task_dir / path}")
        seen.add(path)
        normalized.append(path)
    return tuple(normalized)


def _paths_overlap(first: str, second: str) -> bool:
    first_path = Path(first)
    second_path = Path(second)
    return first_path == second_path or first_path in second_path.parents or second_path in first_path.parents


def load_auxiliary_materials(
    task_dir: Path,
    *,
    full_entries: tuple[str, ...] | None = None,
) -> tuple[tuple[AuxiliaryMaterial, ...], str | None]:
    """Load one optional sidecar declaration.

    A missing declaration is deliberately equivalent to an empty packet so
    existing tasks and callers remain compatible during the migration.
    """

    path = declaration_path(task_dir)
    if not path.exists():
        return (), None
    if not path.is_file():
        raise ValueError(f"Auxiliary-material declaration is not a file: {path}")

    payload = load_json_object(path)
    unknown = sorted(set(payload) - {"schema_version", "auxiliary_materials"})
    if unknown:
        raise ValueError(
            f"Unknown auxiliary-material declaration fields in {path}: {', '.join(unknown)}"
        )
    if payload.get("schema_version") != 1:
        raise ValueError(f"Unsupported auxiliary-material schema in {path}")
    raw_materials = payload.get("auxiliary_materials")
    if not isinstance(raw_materials, list):
        raise ValueError(f"auxiliary_materials must be a list in {path}")

    entries = full_entries if full_entries is not None else _metadata_entries(task_dir)
    entry_set = set(entries)
    materials: list[AuxiliaryMaterial] = []
    seen: set[str] = set()
    for index, raw_item in enumerate(raw_materials):
        if not isinstance(raw_item, dict):
            raise ValueError(f"auxiliary_materials[{index}] must be an object in {path}")
        unknown_item = sorted(set(raw_item) - {"path", "kind"})
        if unknown_item:
            raise ValueError(
                f"Unknown auxiliary-material fields in {path}: {', '.join(unknown_item)}"
            )
        item_path = _validate_relative_path(
            raw_item.get("path"), label=f"auxiliary_materials[{index}].path"
        )
        kind = raw_item.get("kind")
        if kind not in SUPPORTED_AUXILIARY_KINDS:
            raise ValueError(
                f"Unsupported auxiliary-material kind in {path}: {kind!r}. "
                f"Expected one of: {', '.join(sorted(SUPPORTED_AUXILIARY_KINDS))}"
            )
        if item_path not in entry_set:
            raise ValueError(
                f"Auxiliary material must be a full agent entry in {path}: {item_path!r}"
            )
        if not (task_dir / item_path).exists():
            raise FileNotFoundError(f"Auxiliary material does not exist: {task_dir / item_path}")
        if item_path in seen:
            raise ValueError(f"Duplicate auxiliary material in {path}: {item_path!r}")
        for previous in materials:
            if _paths_overlap(previous.path, item_path):
                raise ValueError(
                    f"Overlapping auxiliary materials in {path}: "
                    f"{previous.path!r} and {item_path!r}"
                )
        seen.add(item_path)
        materials.append(AuxiliaryMaterial(path=item_path, kind=kind))

    return tuple(materials), hashlib.sha256(path.read_bytes()).hexdigest()


def _validate_manifest_alignment(task_dir: Path, full_entries: tuple[str, ...]) -> None:
    """Require the two public declarations to agree for migrated tasks."""

    manifest_path = task_dir / "task.json"
    manifest = load_json_object(manifest_path)
    visible_files = manifest.get("visible_files")
    if not isinstance(visible_files, list):
        raise ValueError(f"visible_files must be a list in {manifest_path}")
    normalized = tuple(
        _validate_relative_path(value, label=f"visible_files[{index}]")
        for index, value in enumerate(visible_files)
    )
    if normalized != full_entries:
        raise ValueError(
            f"metadata.json agent_entry_files and task.json visible_files differ for {task_dir}"
        )


def _validate_profile_neutrality(
    task_dir: Path, materials: tuple[AuxiliaryMaterial, ...]
) -> None:
    """Reject core prose that names a packet omitted by ``without_auxiliary``.

    The no-material profile keeps the task statement and public reproduction
    intact. Naming an omitted path there would make the two profiles describe
    different usable tasks, so direct path references are a declaration error.
    """

    for relative_path in CORE_PROFILE_TEXT_FILES:
        document_path = task_dir / relative_path
        if not document_path.is_file():
            continue
        content = document_path.read_text(encoding="utf-8")
        for material in materials:
            if material.path in content:
                raise ValueError(
                    f"Core document {document_path} refers to auxiliary material "
                    f"omitted by {WITHOUT_AUXILIARY}: {material.path!r}"
                )

